import {demoApi} from './demo-api.js';
const BASE='/demos/agent-suitaibility-demo';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rupee=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(n||0);
const date=s=>s?new Date(s).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'}):'—';
const icons={person:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',device:'<rect x="5" y="2" width="14" height="20" rx="3"/><path d="M10 18h4"/>',home:'<path d="m2 11 10-8 10 8M5 10v11h14V10M10 21v-7h4v7"/>',shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4Z"/><path d="m8 12 3 3 5-6"/>',health:'<path d="M9 3h6v6h6v6h-6v6H9v-6H3V9h6Z"/>',briefcase:'<rect x="2" y="7" width="20" height="15" rx="2"/><path d="M8 7V3h8v4M2 13h20M10 13v3h4v-3"/>',card:'<rect x="2" y="4" width="20" height="16" rx="3"/><path d="M2 9h20M6 15h4"/>'};
const icon=(name,green=false)=>`<div class="icon ${green?'green':''}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.shield}</svg></div>`;
const logo=()=>'<span class="brandmark" aria-label="Symbo">symbo<span>.</span></span>';
const statusNames={proposal_created:'Ready to share',sent:'Awaiting customer',awaiting_otp:'Verification pending',payment_pending:'Awaiting payment',ready:'Ready for loan processing'};
let S={role:'agent',screen:'login',step:1,masterTab:'rates',selections:[],products:[],customerRead:new Set(),customerChoices:{},customerConsent:{},customerStage:'review',paymentMode:''};
let polling=null;
const customerId=new URLSearchParams(location.search).get('customer'),customerToken=location.hash.slice(1);
async function api(path,body){return demoApi(path,body,customerId?customerToken:'');}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(S.toastTimer);S.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5500);}
async function act(fn){try{await fn();}catch(e){toast(e.message);}}
function download(name,value,type='application/json'){const url=URL.createObjectURL(new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function head(customer=false){return `<header class="topbar"><div class="top-inner">${logo()}<span class="top-product">Agent suitability demo</span><div class="top-right">${customer?'<span class="tag green">Your protection choices</span>':`<span class="tag">${esc(S.session?.role)} · ${esc(S.session?.code)}</span><button class="link" data-action="home">Home</button><button class="link" data-action="records">Applications</button>${S.session?.role==='agent'?'<button class="link" data-action="masters">Masters</button>':''}<button class="link" data-action="logout">Exit demo</button>`}</div></div></header>`;}
function steps(){return `<div class="stepper">${['Customer & asset','Your needs','Shortlist','Send proposal','Track & complete'].map((s,i)=>`<div class="step ${S.step===i+1?'active':''}"><b>${i+1<S.step?'✓':i+1}</b><span>${s}</span></div>`).join('')}</div>`;}
function field(label,name,value,type='text',extra=''){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function select(label,name,value,options,hint=''){return `<label class="field"><span>${label}</span><select name="${name}">${options.map(o=>{const v=typeof o==='string'?o:o.value,l=typeof o==='string'?o:o.label;return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`;}).join('')}</select>${hint?`<small>${hint}</small>`:''}</label>`;}
function summaryLine(a,b){return `<div class="summary-line"><span>${a}</span><strong>${b}</strong></div>`;}
function fresh(){return {name:'Aarav Demo',email:'aarav.demo@example.com',mobile:'0000000000',age:31,pincode:'400001',city:'Mumbai',state:'Maharashtra',assetId:'mobile-android',brand:'Sample',model:'Android phone',assetCost:45000,loanAmount:35000,tenure:12,condition:'new',usage:'home',warrantyYears:1,purchaseDays:0,answers:{}};}
function login(){return `<main class="login-layout"><section class="login-brand"><div style="background:white;padding:18px;border-radius:8px;width:max-content">${logo()}</div><div><p class="eyebrow" style="color:#8adcac">SYMBO · AGENT JOURNEY</p><h1>Suitable choices.<br>Clear evidence.</h1><p>Help every customer choose benefits that fit their life.</p></div><p class="small">Agent and partner workspace</p></section><section class="login-form"><div class="login-box"><div class="wordlogo">symbo<span>.</span></div><p class="eyebrow">AGENT DEMO</p><h1>Let’s get started.</h1><p class="muted">Explore the agent journey with fictional customer details.</p><div class="role-tabs">${['dealer','agent'].map(r=>`<button class="${S.role===r?'active':''}" data-role="${r}">${icon('person',r==='agent')}${r==='dealer'?'Dealer':'Agent'} view</button>`).join('')}</div><form id="login-form">${field('Demo agent name','code','symbo-agent','text','required maxlength="40"')}<button class="btn full" type="submit">Enter demo workspace →</button><p class="small muted center" style="margin:20px 0 0">Illustrative workspace · no account required</p></form></div></section></main>`;}
function home(){return `${head()}<main class="shell"><div class="hero"><div><p class="eyebrow">YOUR WORKSPACE</p><h1>Every purchase. More possibilities.</h1><p>Choose a loan portfolio to begin a customer journey.</p></div></div><div class="tiles"><button class="tile" data-action="start">${icon('device',true)}<span class="tag green">Available</span><h2>Mobile & Consumer<br>Durable Loans</h2><p>Relevant protection and everyday benefits for the things your customers bring home.</p><span class="arrow">Start application →</span></button><button class="tile unavailable" data-action="business">${icon('briefcase')}<span class="tag gray">Coming next</span><h2>Business<br>Loans</h2><p>Credit Life protection with an automatically completed membership and health declaration form.</p><span class="arrow">View planned journey →</span></button></div><div class="hero"><div><h2>At a glance</h2><p>All customer decisions, in one place.</p></div><button class="link" data-action="records">View applications →</button></div><div class="grid three">${[['Applications',S.proposals.length],['Ready for processing',S.proposals.filter(p=>p.status==='ready').length],['Awaiting customer',S.proposals.filter(p=>!['ready','payment_pending'].includes(p.status)).length]].map(([l,n])=>`<div class="card stat"><b>${n}</b><span class="muted small">${l}</span></div>`).join('')}</div>${S.session.role==='agent'?'<div class="card row"><div><h3>Demo product & pricing masters</h3><p class="muted small" style="margin:0">Manage asset rates, product variants and customer disclosures.</p></div><button class="btn secondary" data-action="masters">Manage →</button></div>':''}</main>`;}
function customerForm(){const a=S.application;return `<div class="hero"><div><p class="eyebrow">CONSUMER DURABLE LOAN</p><h1>Start with the customer.</h1><p>Capture the purchase details once. We’ll use them throughout the journey.</p></div></div><form id="application-form"><div class="application-details"><div><div class="card"><div class="row"><h2>Customer details</h2><span class="tag">01</span></div><div class="formgrid">${field('Full name','name',a.name,'text','required autocomplete="name"')}${field('Age','age',a.age,'number','required min="18" max="80"')}${field('Mobile number','mobile',a.mobile,'tel','required pattern="[0-9]{10}" maxlength="10" inputmode="numeric"')}${field('Email','email',a.email,'email','required autocomplete="email"')}${field('PIN code','pincode',a.pincode,'text','required pattern="[0-9]{6}" maxlength="6" inputmode="numeric"')}${field('City','city',a.city,'text','required')}${field('State','state',a.state,'text','required')}</div></div><div class="card"><div class="row"><h2>What are they purchasing?</h2><span class="tag">02</span></div><div class="formgrid">${select('Purpose of loan / asset','assetId',a.assetId,[{value:'',label:'Select product'},...S.masters.assets.map(x=>({value:x.id,label:x.name}))])}${field('Brand','brand',a.brand,'text','required')}${field('Model','model',a.model,'text','required')}${field('Asset invoice value (₹)','assetCost',a.assetCost,'number','required min="1000" max="1000000" step="0.01"')}${field('Loan amount (₹)','loanAmount',a.loanAmount,'number','required min="1000" max="1000000" step="0.01"')}${select('Loan tenure (months)','tenure',a.tenure,[3,6,9,12,18,24,36,48,60].map(v=>({value:v,label:v+' months'})))}${select('Asset condition','condition',a.condition,[{value:'new',label:'New'},{value:'used',label:'Used'}])}${select('Asset usage','usage',a.usage,[{value:'home',label:'Personal / residential'},{value:'commercial',label:'Commercial'}])}${field('Days since purchase','purchaseDays',a.purchaseDays,'number','required min="0" max="365"')}</div><div class="note" style="margin-top:18px">Extended Warranty is priced on the asset’s invoice value. Loan amount is captured separately.</div></div></div></div><div class="dock"><div class="dock-inner"><span class="small muted">Step 1 of 5 · Customer & purchase</span><button class="btn" type="submit">Understand needs →</button></div></div></form>`;}
function needs(){const a=S.application;const qs=S.questions.filter(q=>(!q.mobileOnly||a.assetId.startsWith('mobile-'))&&(!q.depends||a.answers.health&&a.answers.health!=='None'));return `<div class="hero"><div><p class="eyebrow">A FEW RELEVANT QUESTIONS</p><h1>Understand the customer’s needs.</h1><p>Answer what the customer shares. You can continue at any time; recommendations use only the answers provided.</p></div></div><form id="needs-form"><div class="layout"><div class="card">${qs.map((q,i)=>`<div class="question"><div class="row"><h3>${i+1}. ${esc(q.title)}</h3>${a.answers[q.id]?`<button type="button" class="link" data-clear-answer="${q.id}">Clear</button>`:''}</div><p>${esc(q.hint)}</p><div class="pillgroup">${q.options.map(o=>`<label class="pill"><input type="radio" name="${q.id}" value="${esc(o)}" ${a.answers[q.id]===o?'checked':''}><span>${esc(o)}</span></label>`).join('')}</div></div>`).join('')}</div><aside class="sticky"><div class="card"><h3>Recommendations so far</h3><p class="small muted">${Object.keys(a.answers).length} answered · ${S.products.filter(p=>p.recommended).length} recommended</p>${S.products.filter(p=>p.recommended).map(p=>`<p class="small"><strong>${esc(p.name)}</strong><br>${esc(p.reason)}</p>`).join('')}${summaryLine('Asset',esc(S.masters.assets.find(x=>x.id===a.assetId).name))}${summaryLine('Invoice value',rupee(a.assetCost))}${summaryLine('Loan',rupee(a.loanAmount))}${summaryLine('Tenure',a.tenure+' months')}<div class="divider"></div><p class="small muted">Customers can decline every optional product. Existing protection is considered to help avoid overlap.</p></div></aside></div><div class="dock"><div class="dock-inner"><button type="button" class="link" data-action="back-details">← Details</button><button class="btn" type="submit">View products →</button></div></div></form>`;}
const productIcon=id=>({ew:'device',adld:'shield',health:'health',epicure:'home',galaxy:'health',insta:'card'}[id]);
async function updateNeeds(){const a=JSON.stringify(S.application);const r=await api('/assess',{application:S.application});if(a!==JSON.stringify(S.application)||S.step!==2)return;S.products=r.products;const y=scrollY;render();scrollTo(0,y);}
function productCard(p){const s=S.selections.find(x=>x.id===p.id),v=p.variants.find(x=>x.name===(s?.variant||p.variant));return `<article class="card product ${s?'selected':''}"><div class="row start">${icon(productIcon(p.id),!!s)}<span class="tag ${p.recommended?'green':p.eligible?'gray':'amber'}">${p.recommended?'Recommended':p.eligible?'Alternative':'Not eligible'}</span></div><h2 style="margin:18px 0 6px">${esc(p.name)}</h2><p class="description">${esc(p.description)}</p>${p.variants.length?select('Choose plan','variant-'+p.id,s?.variant||p.variant,p.variants.map(v=>v.name)):''}<div class="reason"><strong>${p.recommended?'Why this fits':'Fitment check'}</strong>${esc(p.reason)}</div><button class="link" data-terms="${p.id}">Benefits & terms ↗</button>${s&&!p.recommended?`<label class="field"><span>Reason for offering this alternative</span><textarea data-override="${p.id}" placeholder="Record the customer’s stated need">${esc(s.overrideReason)}</textarea></label>`:''}<div class="divider"></div><div class="product-bottom"><div><div class="price">${rupee(v?.price??p.price)}</div><span class="small muted">${p.id==='ew'?`${((v?.rate||0)*100).toFixed(4)}% of invoice + GST`:esc(p.priceStatus)}</span></div><button class="btn ${s?'secondary':''}" data-toggle="${p.id}" ${!p.eligible?'disabled':''}>${s?'✓ Selected':'+ Add'}</button></div></article>`;}
function shortlist(){const recommended=S.products.filter(p=>p.recommended),other=S.products.filter(p=>!p.recommended),strict=S.masters.recommendationMode==='strict';return `<div class="hero"><div><p class="eyebrow">RECOMMENDATIONS</p><h1>Relevant benefits. Clear choices.</h1><p>Based on the answers provided. Your customer makes the final decision.</p></div><button class="link" data-action="back-needs">Edit answers</button></div>${recommended.length?`<div class="grid">${recommended.map(productCard).join('')}</div>`:'<div class="note" style="margin-bottom:20px">No recommendations yet. Answer relevant questions to identify a fit.</div>'}${!strict?`<details class="all-products" ${S.allProductsOpen?'open':''}><summary>All products · ${other.length} other products</summary><p class="small muted">You may offer another eligible product by recording the customer’s need. Eligibility requirements still apply.</p><div class="grid">${other.map(productCard).join('')}</div></details>`:'<p class="small muted">Only products supported by the customer’s answers can be offered.</p>'}<div class="dock"><div class="dock-inner"><div><span class="small muted">${S.selections.length} selected · optional benefits</span><div class="price">${rupee(selectionTotal())}</div></div><button class="btn" data-action="review">Review proposal →</button></div></div>`;}
function selectionTotal(){return S.selections.reduce((n,s)=>{const p=S.products.find(p=>p.id===s.id);return n+(p.variants.find(v=>v.name===s.variant)?.price??p.price);},0);}
function review(){const a=S.application,q=S.quote;return `<div class="hero"><div><p class="eyebrow">READY FOR THE CUSTOMER</p><h1>One final look.</h1><p>Send the proposal for independent review and individual consent.</p></div></div><div class="layout"><div><div class="card"><h2>Customer & delivery</h2>${summaryLine('Name',esc(a.name))}${summaryLine('Email',esc(a.email))}${summaryLine('Mobile',esc(a.mobile))}${summaryLine('Purchase',esc(a.brand+' '+a.model))}<div class="note green" style="margin-top:18px">In this demo, the customer view opens in this browser. Email delivery and verification are simulated.</div></div><div class="card"><h2>Shortlisted products</h2>${q.items.length?q.items.map(p=>`<div class="summary-line"><div><strong>${esc(p.name)}</strong><p class="small muted" style="margin:4px 0">${esc(p.variant||'1-year plan')}</p></div><strong>${rupee(p.price)}</strong></div>`).join(''):'<p class="muted">No optional products selected. The customer can confirm continuing without add-ons.</p>'}<div class="divider"></div>${summaryLine('Total optional benefits',rupee(q.total))}<p class="small muted">The customer’s total will update if they decline a product.</p></div></div><aside class="sticky"><div class="card"><p class="eyebrow">CUSTOMER JOURNEY</p><ol class="timeline"><li>Review each product<small>Features, price and terms</small></li><li>Accept or decline independently<small>No preselected consent</small></li><li>Choose how to pay<small>Separately or with the loan</small></li><li>Verify with demo code<small>Choice record linked to this step</small></li></ol></div></aside></div><div class="dock"><div class="dock-inner"><button class="link" data-action="back-shortlist">← Shortlist</button><button class="btn" data-action="create">Create & continue →</button></div></div>`;}
function track(){const p=S.current.proposal;return `<div class="hero"><div><p class="eyebrow">${esc(p.reference)}</p><h1>${p.verifiedAt?'Customer decision received.':'Ready when your customer is.'}</h1><p>${esc(p.application.name)} · ${statusNames[p.status]||p.status}</p></div><button class="btn secondary" data-action="refresh">Refresh ↻</button></div><div class="layout"><div><div class="card"><div class="row"><h2>Application status</h2><span class="tag ${p.verifiedAt?'green':'amber'}">${p.verifiedAt?'Demo code verified':'Action pending'}</span></div>${summaryLine('Proposal delivery',p.lastSentAt?'Simulated send recorded':'Not sent yet')}${summaryLine('Customer email',esc(p.application.email))}${summaryLine('Individual decisions',p.choices?`${p.choices.filter(c=>c.decision==='accept').length} accepted · ${p.choices.filter(c=>c.decision==='decline').length} declined`:'Awaiting review')}${summaryLine('Demo verification',p.verifiedAt?date(p.verifiedAt):'Awaiting confirmation')}${summaryLine('Payment choice',p.paymentMode==='loan'?'Add to loan':p.paymentMode==='separate'?'Pay separately':p.paymentMode==='none'?'No add-ons':'Awaiting choice')}${p.verifiedAt?`<div class="note green" style="margin-top:18px">${p.paymentMode==='separate'?'Consent is complete. Separate payment remains pending; payment collection must be completed before disbursement.':'Good to go. The consent record is ready to pass to the loan system.'}</div>`:''}<div class="actions no-print"><button class="btn" data-action="send" ${p.verifiedAt?'disabled':''}>${p.lastSentAt?'Simulate resend':'Simulate send'} ↗</button><button class="btn secondary" data-action="customer-preview">Open customer view ↗</button></div></div><div class="card"><h2>Product-by-product record</h2>${p.quote.items.map(i=>{const c=p.choices?.find(c=>c.id===i.id);return `<div class="summary-line"><div><strong>${esc(i.name)}</strong><p class="small muted" style="margin:3px 0">${esc(i.variant)} · ${rupee(i.price)}</p></div><span class="tag ${c?.decision==='accept'?'green':'gray'}">${c?esc(c.decision):'Pending'}</span></div>`;}).join('')||'<p class="muted">Customer continues without optional products.</p>'}</div><div class="card"><h2>Application history</h2><ol class="timeline">${[...S.current.events].reverse().map(e=>`<li>${esc(eventLabel(e.kind))}<small>${date(e.at)}</small></li>`).join('')}</ol></div></div><aside class="sticky"><div class="card"><p class="eyebrow">FINANCIAL SUMMARY</p>${summaryLine('Base loan',rupee(p.application.loanAmount))}${summaryLine('Accepted benefits',rupee(p.acceptedTotal??0))}${summaryLine('Added to loan',rupee(p.paymentMode==='loan'?p.acceptedTotal:0))}<div class="divider"></div><div class="small muted">${p.paymentMode==='loan'?'Requested financed amount':'Base loan amount'}</div><div class="bigprice">${rupee(p.application.loanAmount+(p.paymentMode==='loan'?p.acceptedTotal:0))}</div><p class="small muted" style="margin-top:14px">Final EMI and disbursement are determined by the loan system. Add-on prices do not include financing interest.</p></div><div class="card no-print"><h3>Documents & handoff</h3><button class="btn secondary full" data-action="evidence">Download full record</button><button class="btn secondary full" style="margin-top:10px" data-action="print">Print consent summary</button><button class="btn blue full" style="margin-top:10px" data-action="handoff" ${!p.verifiedAt?'disabled':''}>Download loan-system handoff</button><p class="small muted" style="margin:14px 0 0">Includes decisions, price snapshots, terms, payment choice and verification evidence.</p></div></aside></div>`;}
const eventLabel=k=>({proposal_created:'Proposal created',proposal_email_simulated:'Simulated proposal send',customer_link_renewed:'Customer link renewed',customer_view_opened:'Customer preview opened',choices_saved:'Customer choices saved',otp_requested:'Verification code requested',otp_attempt_failed:'Unsuccessful verification attempt',consent_verified:'Individual consents verified'}[k]||k.replaceAll('_',' '));
function records(){return `${head()}<main class="shell"><div class="hero"><div><p class="eyebrow">CONSUMER DURABLE APPLICATIONS</p><h1>Every demo decision, visible.</h1><p>Track customer responses and retrieve consent evidence.</p></div><button class="btn" data-action="start">New application +</button></div>${S.proposals.length?S.proposals.map(p=>`<button class="card full record-card" data-record="${p.id}" style="display:block;width:100%;text-align:left;color:inherit"><div class="row"><div><p class="eyebrow">${esc(p.reference)}</p><h3>${esc(p.name)}</h3><span class="small muted">${date(p.createdAt)}</span></div><div style="text-align:right"><span class="tag ${p.status==='ready'?'green':'gray'}">${statusNames[p.status]}</span><div class="price" style="margin-top:12px">${rupee(p.total)}</div></div></div></button>`).join(''):'<div class="card empty">No demo applications yet. Start your first customer journey.</div>'}</main>`;}
function masters(){const m=S.editMasters||structuredClone(S.masters);S.editMasters=m;return `${head()}<main class="shell"><div class="hero"><div><p class="eyebrow">PRODUCT OPERATIONS</p><h1>A visible product rulebook.</h1><p>Version ${m.version} · Browser-local changes apply to new demo proposals. Existing records stay unchanged.</p></div></div><div class="tabs">${[['rates','EW pricing'],['products','Products & variants'],['questions','Suitability rules'],['terms','Disclosures']].map(([id,label])=>`<button class="${S.masterTab===id?'active':''}" data-master-tab="${id}">${label}</button>`).join('')}</div><div class="card">${S.masterTab==='rates'?`<div class="row"><div><h2>Extended Warranty · asset rates</h2><p class="small muted">Illustrative rates · editable in this browser</p></div><button class="btn secondary" data-action="export-rates">Export CSV</button></div><div class="formgrid">${field('GST rate (%)','master-tax',m.ewTaxPercent,'number','min="0" max="50"')}${select('Rate tax treatment','master-tax-mode',m.ewTaxMode,[{value:'exclusive',label:'GST added to base price'},{value:'inclusive',label:'GST included in price'}])}</div><div class="note green">Price = asset invoice value × rate. ${m.ewTaxMode==='exclusive'?'GST is added separately.':'GST is included.'} A blank rate means the term is unavailable.</div><div class="table-wrap" style="margin-top:20px"><table><thead><tr><th>Asset category</th><th>1 year (%)</th><th>2 years (%)</th><th>3 years (%)</th></tr></thead><tbody>${m.assets.map(a=>`<tr><td>${esc(a.name)}</td>${[1,2,3].map(y=>`<td><input aria-label="${esc(a.name)} ${y} year rate" type="number" min="0" max="50" step="0.000001" data-rate-asset="${a.id}" data-year="${y}" value="${a.rates[y]===undefined?'':Number((a.rates[y]*100).toFixed(6))}" placeholder="Unavailable"></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="actions"><label class="btn secondary">Import rates CSV<input id="import-rates" type="file" accept=".csv,text/csv" hidden></label><span class="small muted">Columns: asset_id, year_1_percent, year_2_percent, year_3_percent</span></div>`:S.masterTab==='products'?`<h2>Product availability & pricing</h2><p class="small muted">Illustrative demo prices are preloaded. Changes are stored in this browser only.</p>${m.products.map(p=>`<div class="question"><div class="row"><h3>${esc(p.name)}</h3><label class="check"><input type="checkbox" data-active="${p.id}" ${p.active?'checked':''}>Active</label></div><p>${esc(p.source)}</p>${p.id==='ew'?'<p>Rate comes from the selected asset and cover term.</p>':p.variants.length?`<div class="formgrid">${p.variants.map((v,i)=>`<label class="field"><span>${esc(v.name)} (₹)</span><input type="number" min="0" max="100000" step="0.01" value="${v.price}" data-variant-price="${p.id}" data-index="${i}"></label>`).join('')}</div>`:`<label class="field"><span>${p.id==='adld'?'Asset rate (%) · configured total':'Programme price (₹)'}</span><input type="number" min="0" max="${p.id==='adld'?50:100000}" step="0.01" value="${p.price}" data-price="${p.id}"></label>`}</div>`).join('')}`:S.masterTab==='questions'?`<h2>Recommendation settings</h2>${select('Product selection mode','recommendation-mode',m.recommendationMode||'flexible',[{value:'flexible',label:'Flexible — recommendations and all eligible products'},{value:'strict',label:'Strict — recommended products only'}])}<p class="small muted">Flexible selection requires a recorded reason for alternatives. Strict selection allows only products supported by positive answers. Unanswered questions never imply a need.</p><h2>Question-to-product mapping</h2><p class="small muted">The same illustrative rules power recommendations and the stored explanation.</p>${S.questions.map(q=>`<div class="question"><h3>${esc(q.title)}</h3><p>${esc(q.hint)}</p><div class="small">${q.options.map(esc).join(' · ')}</div></div>`).join('')}<div class="note" style="margin-top:20px">Eligibility is evaluated before recommendation. EW requires a new, home-use asset with one-year manufacturer warranty and same-day purchase; ADLD is mapped to new mobiles; Hospital Cash & EMI Support requires age 18–60; Future Purchase Programme uses age, CIBIL, credit checks and completed EMIs. Customer answers determine ranking and variants. Questions and mappings are visible here; pricing, availability and disclosures are editable.</div>`:`<h2>Per-product customer disclosures</h2><p class="small muted">Each proposal preserves a versioned copy of these disclosures.</p>${m.products.map(p=>`<label class="field"><span>${esc(p.name)}</span><textarea data-terms-edit="${p.id}" style="min-height:180px">${esc(p.terms)}</textarea></label>`).join('')}`}</div><div class="dock"><div class="dock-inner"><span class="small muted">Current published version: ${S.masters.version}</span><button class="btn" data-action="save-masters">Save demo changes →</button></div></div></main>`;}
function render(){clearInterval(polling);$('#app').innerHTML=S.screen==='login'?login():S.screen==='home'?home():S.screen==='records'?records():S.screen==='masters'?masters():`${head()}<main class="shell">${steps()}${S.step===1?customerForm():S.step===2?needs():S.step===3?shortlist():S.step===4?review():track()}</main>`;bind();if(S.screen==='journey'&&S.step===5)polling=setInterval(()=>refreshTrack(true),10000);}
function bind(){
 $('.all-products')?.addEventListener('toggle',e=>S.allProductsOpen=e.target.open);
 $$('[data-action]').forEach(el=>el.onclick=()=>act(()=>actions[el.dataset.action]?.(el)));
 $$('[data-role]').forEach(el=>el.onclick=()=>{S.role=el.dataset.role;render();});
 $('#login-form')?.addEventListener('submit',e=>{e.preventDefault();act(async()=>{const f=new FormData(e.target);S.session=await api('/login',{role:S.role,code:f.get('code'),pin:f.get('pin')});await bootstrap();S.screen='home';render();});});
 $('#application-form')?.addEventListener('submit',e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));for(const k of ['age','assetCost','loanAmount','tenure','purchaseDays'])f[k]=Number(f[k]);S.application={...S.application,...f,warrantyYears:1};S.products=[];if(f.loanAmount>f.assetCost)return toast('Loan amount cannot exceed asset cost');S.step=2;render();window.scrollTo(0,0);});
 $('#application-form [name="assetCost"]')?.addEventListener('change',e=>{const loan=$('[name="loanAmount"]');if(Number(loan.value)===S.application.assetCost)loan.value=e.target.value;});
 $('#needs-form')?.addEventListener('change',e=>act(async()=>{S.application.answers[e.target.name]=e.target.value;if(e.target.name==='health'&&e.target.value==='None')delete S.application.answers.members;await updateNeeds();}));
 $$('[data-clear-answer]').forEach(el=>el.onclick=()=>act(async()=>{delete S.application.answers[el.dataset.clearAnswer];if(el.dataset.clearAnswer==='health')delete S.application.answers.members;await updateNeeds();}));
 $('#needs-form')?.addEventListener('submit',e=>{e.preventDefault();act(async()=>{S.application.answers={...S.application.answers,...Object.fromEntries(new FormData(e.target))};const r=await api('/assess',{application:S.application});S.products=r.products;S.selections=[];S.step=3;render();scrollTo(0,0);});});
 $$('[data-toggle]').forEach(el=>el.onclick=()=>{const id=el.dataset.toggle,p=S.products.find(p=>p.id===id);if(S.selections.some(s=>s.id===id))S.selections=S.selections.filter(s=>s.id!==id);else S.selections.push({id,variant:$(`[name="variant-${id}"]`)?.value||p.variant,overrideReason:''});const y=scrollY;render();scrollTo(0,y);});
 $$('[name^="variant-"]').forEach(el=>el.onchange=()=>{const id=el.name.slice(8),s=S.selections.find(x=>x.id===id),p=S.products.find(x=>x.id===id);if(s)s.variant=el.value;else p.variant=el.value;const y=scrollY;render();scrollTo(0,y);});
 $$('[data-override]').forEach(el=>el.oninput=()=>{S.selections.find(x=>x.id===el.dataset.override).overrideReason=el.value;});
 $$('[data-terms]').forEach(el=>el.onclick=()=>showTerms(S.products.find(p=>p.id===el.dataset.terms)));
 $$('[data-record]').forEach(el=>el.onclick=()=>act(async()=>{S.current=await api('/proposals/'+el.dataset.record);S.screen='journey';S.step=5;render();scrollTo(0,0);}));
 $$('[data-master-tab]').forEach(el=>el.onclick=()=>{S.masterTab=el.dataset.masterTab;render();});
 $$('[data-rate-asset]').forEach(el=>el.oninput=()=>{const a=S.editMasters.assets.find(a=>a.id===el.dataset.rateAsset);if(el.value==='')delete a.rates[el.dataset.year];else a.rates[el.dataset.year]=Number(el.value)/100;});
 $('[name="recommendation-mode"]')?.addEventListener('change',e=>S.editMasters.recommendationMode=e.target.value);
 $('[name="master-tax"]')?.addEventListener('input',e=>S.editMasters.ewTaxPercent=Number(e.target.value));
 $('[name="master-tax-mode"]')?.addEventListener('change',e=>S.editMasters.ewTaxMode=e.target.value);
 $$('[data-active]').forEach(el=>el.onchange=()=>S.editMasters.products.find(p=>p.id===el.dataset.active).active=el.checked);
 $$('[data-price]').forEach(el=>el.oninput=()=>S.editMasters.products.find(p=>p.id===el.dataset.price).price=Number(el.value));
 $$('[data-variant-price]').forEach(el=>el.oninput=()=>S.editMasters.products.find(p=>p.id===el.dataset.variantPrice).variants[Number(el.dataset.index)].price=Number(el.value));
 $$('[data-terms-edit]').forEach(el=>el.oninput=()=>S.editMasters.products.find(p=>p.id===el.dataset.termsEdit).terms=el.value);
 $('#import-rates')?.addEventListener('change',e=>act(async()=>{const file=e.target.files[0];if(!file)return;const lines=(await file.text()).trim().split(/\r?\n/);if(lines[0].trim()!=='asset_id,year_1_percent,year_2_percent,year_3_percent')throw Error('Use the exported CSV column format');const next=structuredClone(S.editMasters.assets),seen=new Set();for(const line of lines.slice(1)){const [id,...rates]=line.split(',');const a=next.find(a=>a.id===id);if(!a||rates.length!==3||seen.has(id))throw Error('Invalid or duplicate asset row');seen.add(id);a.rates={};rates.forEach((s,i)=>{if(s.trim()==='')return;const n=Number(s);if(!Number.isFinite(n)||n<0||n>50)throw Error('Rate must be 0–50%');a.rates[i+1]=n/100;});}S.editMasters.assets=next;render();toast('Rates loaded for review. Save to publish.');}));
}
async function bootstrap(){Object.assign(S,await api('/bootstrap'));}
async function refreshTrack(quiet=false){try{const next=await api('/proposals/'+S.current.proposal.id);if(JSON.stringify(next)!==JSON.stringify(S.current)){S.current=next;render();}else if(!quiet)toast('Status is up to date');}catch(e){if(!quiet)throw e;}}
function showTerms(p){const div=document.createElement('div');div.className='modal-overlay';div.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="Product terms"><div class="row"><h2>${esc(p.name)}</h2><button class="link" id="close-modal">Close ✕</button></div><p>${esc(p.description)}</p><p style="white-space:pre-line;line-height:1.8;font-size:14px">${esc(p.terms)}</p></section>`;document.body.append(div);$('#close-modal').onclick=()=>div.remove();$('#close-modal').focus();div.onclick=e=>{if(e.target===div)div.remove();};}
function showDialog(title,body){const previous=document.activeElement,overlay=document.createElement('div');overlay.className='modal-overlay';overlay.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><h2>${esc(title)}</h2>${body}</section>`;document.body.append(overlay);const close=()=>{overlay.remove();previous?.focus();};overlay.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();overlay.querySelector('[data-dismiss]')?.click();}if(e.key==='Tab'){const nodes=[...overlay.querySelectorAll('button,a[href],input')].filter(n=>!n.disabled);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});overlay.querySelector('button,input,a')?.focus();return {overlay,close};}
function showShareLink(path){const link=new URL(path,S.publicUrl||location.origin).href;const {overlay,close}=showDialog('Customer preview',`<p>Open the simulated customer view in this browser. Demo records are stored only here, so this link will not work on another device.</p><label class="field"><span>Customer link</span><input id="share-url" readonly value="${esc(link)}"></label><div class="actions"><button class="btn" id="copy-link">Copy link</button><a class="btn secondary" href="${esc(link)}" target="_blank" rel="noopener noreferrer">Open in new window ↗</a><button class="link" data-dismiss>Close</button></div>`);overlay.querySelector('[data-dismiss]').onclick=close;overlay.querySelector('#copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(link);toast('Customer link copied');}catch{overlay.querySelector('#share-url').select();toast('Select and copy the customer link');}};}
const declineNotes={ew:'Extended Warranty helps with eligible repair costs after the manufacturer warranty ends. Without it, these repairs would be your responsibility unless covered elsewhere.',adld:'Accidental & Liquid Damage provides cover for eligible drops and spills, subject to its limits and deductible. Manufacturer warranties may not include these incidents.',health:'Wellness Access provides the health services and wallet benefits described in this plan. Consider whether your existing arrangements already meet these needs.',epicure:'Home & Digital Assist includes the appliance, digital and lifestyle services listed in your selected plan. Check whether those services would be useful to you.',galaxy:'Hospital Cash & EMI Support offers fixed benefits for eligible hospitalisation and accidents. Consider whether you already have similar support for these situations.',insta:'Future Purchase Programme supports eligible future purchases, subject to separate credit approval. You can continue this application without it.'};
function confirmDeclines(choices){const declined=S.customer.quote.items.filter(i=>choices.some(c=>c.id===i.id&&c.decision==='decline'));if(!declined.length)return Promise.resolve(true);return new Promise(resolve=>{const {overlay,close}=showDialog('Continue without these products?',`<p>You have chosen to decline the following products. Here is what each would provide:</p>${declined.map(i=>`<div class="decline-item"><h3>${esc(i.name)}</h3><p class="small muted">${esc(declineNotes[i.id]||i.description)}</p></div>`).join('')}<p class="small">These products are optional. Your declines will be respected and your application can continue.</p><div class="actions"><button class="btn secondary" data-dismiss>Review choices</button><button class="btn secondary" id="keep-declines">Continue with my choices</button></div>`);overlay.querySelector('[data-dismiss]').onclick=()=>{close();resolve(false);};overlay.querySelector('#keep-declines').onclick=()=>{close();resolve(true);};});}

const actions={
 home:async()=>{await bootstrap();S.screen='home';render();},logout:async()=>{await api('/logout',{});S.screen='login';render();},
 start:()=>{S.application=fresh();S.selections=[];S.products=[];S.allProductsOpen=false;S.step=1;S.screen='journey';render();scrollTo(0,0);},
 business:()=>{const div=document.createElement('div');div.className='modal-overlay';div.innerHTML='<section class="modal"><p class="eyebrow">NEXT PORTFOLIO</p><h2>Business Loan · Credit Life</h2><p>This journey will reuse customer review, email verification and consent records, with illustrative age and tenure pricing and a prefilled membership and health declaration form.</p><p>The MEF will carry the agent’s entries and the customer’s confirmed declarations into the original form.</p><button class="btn" id="close-business">Back to portfolios</button></section>';document.body.append(div);$('#close-business').onclick=()=>div.remove();},
 records:async()=>{await bootstrap();S.screen='records';render();},masters:async()=>{await bootstrap();S.editMasters=structuredClone(S.masters);S.screen='masters';render();},
 'back-details':()=>{S.step=1;render();},'back-needs':()=>{S.step=2;render();},'back-shortlist':()=>{S.step=3;render();},
 review:async()=>{S.quote=await api('/quote',{application:S.application,selections:S.selections});S.step=4;render();scrollTo(0,0);},
 create:async(el)=>{el.disabled=true;try{const r=await api('/proposals',{application:S.application,selections:S.selections});S.customerPath=r.customerPath;S.current=await api('/proposals/'+r.proposal.id);S.step=5;render();scrollTo(0,0);}finally{el.disabled=false;}},
 send:async(el)=>{el.disabled=true;try{const r=await api('/proposals/'+S.current.proposal.id+'/send',{});S.customerPath=r.customerPath;S.current=await api('/proposals/'+r.proposal.id);render();toast('Simulated send recorded. Open the customer view to continue.');}finally{el.disabled=false;}},
 'customer-preview':async()=>{const r=await api('/proposals/'+S.current.proposal.id+'/preview-link',{});S.customerPath=r.customerPath;showShareLink(r.customerPath);},
 refresh:()=>refreshTrack(),evidence:()=>download(S.current.proposal.reference+'-consent-record.json',S.current),
 print:()=>window.print(),handoff:()=>{const p=S.current.proposal;if(!p.verifiedAt)return;download(p.reference+'-loan-handoff.json',{portfolio:p.portfolio,proposalReference:p.reference,customer:p.application,acceptedProducts:p.quote.items.filter(i=>p.choices.some(c=>c.id===i.id&&c.decision==='accept')),decisions:p.choices,paymentMode:p.paymentMode,paymentStatus:p.paymentMode==='separate'?'pending':'not_collected_separately',baseLoan:p.application.loanAmount,financedAddons:p.paymentMode==='loan'?p.acceptedTotal:0,consent:p.verification,masterVersion:p.quote.masterVersion,disbursementStatus:'not_initiated'});},
 'save-masters':async()=>{const r=await api('/masters',{masters:S.editMasters,expectedVersion:S.masters.version});S.masters=r.masters;S.editMasters=structuredClone(r.masters);render();toast('Demo rules saved. New quotes use version '+r.masters.version);},
 'export-rates':()=>download('symbo-demo-ew-rates.csv','asset_id,year_1_percent,year_2_percent,year_3_percent\n'+S.editMasters.assets.map(a=>[a.id,...[1,2,3].map(y=>a.rates[y]===undefined?'':Number((a.rates[y]*100).toFixed(6)))].join(',')).join('\n'),'text/csv')
};
function highlightConsent(id){const card=$('#product-'+id);card?.scrollIntoView({behavior:'smooth',block:'center'});card?.querySelector('input[data-consent],button[data-decision]')?.focus({preventScroll:true});}
function reviewForAcceptance(id){const item=S.customer.quote.items.find(i=>i.id===id);const {overlay,close}=showDialog('Review '+item.name,`<p class="small muted">Read the benefits, exclusions and terms below. Acceptance applies only to this product.</p><div class="terms acceptance-terms" tabindex="0">${esc(item.terms)}<p>End of product disclosure</p></div><p class="small muted" id="read-progress" role="status">Scroll to the end to enable acceptance.</p><div class="actions"><button class="btn secondary" data-dismiss>Back to choices</button><button class="btn" id="accept-reviewed" disabled>Accept product · ${rupee(item.price)}</button></div>`);const box=overlay.querySelector('.acceptance-terms'),button=overlay.querySelector('#accept-reviewed');const check=()=>{if(box.clientHeight>0&&box.scrollTop+box.clientHeight>=box.scrollHeight-8){button.disabled=false;overlay.querySelector('#read-progress').textContent='Disclosure reviewed. You can now accept this product.';}};box.addEventListener('scroll',check);requestAnimationFrame(check);overlay.querySelector('[data-dismiss]').onclick=close;button.onclick=()=>{if(button.disabled)return;S.customerRead.add(id);S.customerChoices[id]='accept';S.customerConsent[id]=false;close();renderCustomer();highlightConsent(id);};}
function downloadConsentRecord(p){const html=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(p.reference)} · Consent record</title><style>body{font:16px/1.6 Arial,sans-serif;max-width:800px;margin:32px auto;padding:0 20px;color:#00344b}h1,h2{color:#00875b}section{border:1px solid #ccd7e1;border-radius:10px;padding:20px;margin:20px 0}p{white-space:pre-line}.terms{font-size:14px;color:#374151} @media print{section{break-inside:avoid}}</style></head><body><h1>Symbo · Demo choice record</h1><p>Reference: ${esc(p.reference)}<br>Customer: ${esc(p.application.name)}<br>Verified: ${esc(date(p.verifiedAt))}<br>Verification: Simulated demo code<br>Disclosure version: ${esc(p.quote.masterVersion)}</p>${p.quote.items.map(i=>{const c=p.choices.find(c=>c.id===i.id);return `<section><h2>${esc(i.name)}</h2><p>Decision: ${c.decision==='accept'?'Accepted — individual consent given':'Declined'}<br>Plan: ${esc(i.variant||'One-year cover')}<br>Price: ${rupee(i.price)}</p><h3>Product disclosure</h3><p class="terms">${esc(i.terms)}</p></section>`;}).join('')}<p><strong>Total accepted: ${rupee(p.acceptedTotal)}</strong><br>Payment choice: ${p.paymentMode==='loan'?'Add to loan':p.paymentMode==='separate'?'Pay separately':'No add-ons'}<br>Verification reference: ${esc(p.verification?.challengeId)}</p></body></html>`;download(p.reference+'-consent-record.html',html,'text/html');}

function customerTotal(){return S.customer.quote.items.filter(i=>S.customerChoices[i.id]==='accept').reduce((n,i)=>n+i.price,0);}
function customerReview(){const p=S.customer;return `<p class="eyebrow">${esc(p.reference)}</p><h1>A few choices.<br>Made by you.</h1><p class="muted">Review the products shortlisted for your ${esc(p.application.brand+' '+p.application.model)}. You decide what to keep.</p><div class="note green" style="margin-bottom:20px">Every product is optional. Read its terms, then accept or decline it individually.</div>${p.quote.items.map(i=>`<article class="card consent-product" id="product-${i.id}"><div class="row start">${icon(productIcon(i.id),S.customerChoices[i.id]==='accept')}<div style="text-align:right"><div class="price">${rupee(i.price)}</div><span class="small muted">${esc(i.variant||'1-year plan')}</span></div></div><h2 style="margin:18px 0 8px">${esc(i.name)}</h2><p class="small muted">${esc(i.description)}</p>${i.id==='ew'?`<div class="note" style="margin-bottom:16px">Base ${rupee(i.base)} + GST ${rupee(i.tax)} = ${rupee(i.price)}</div>`:''}<details data-disclosure="${i.id}"><summary>Read benefits, exclusions & terms</summary><div class="terms" tabindex="0" data-terms-scroll="${i.id}">${esc(i.terms)}<p class="terms-end">End of product disclosure</p></div><p class="small muted">Read the full disclosure before confirming acceptance.</p></details>${p.quote.items.filter(x=>x.recommended).slice(0,2).some(x=>x.id===i.id)?'<div class="recommendation-label"><span class="tag green">Recommended for your needs</span></div>':''}<div class="decision"><button class="btn accept-choice ${S.customerChoices[i.id]==='accept'?'chosen':''}" aria-pressed="${S.customerChoices[i.id]==='accept'}" data-decision="accept" data-id="${i.id}">${S.customerChoices[i.id]==='accept'?'✓ Accepted':S.customerRead.has(i.id)?'Accept product':'Review & accept'}</button><button class="btn secondary ${S.customerChoices[i.id]==='decline'?'declined':''}" aria-pressed="${S.customerChoices[i.id]==='decline'}" data-decision="decline" data-id="${i.id}">${S.customerChoices[i.id]==='decline'?'Declined':'Decline product'}</button></div>${S.customerChoices[i.id]==='accept'?`<label class="check"><input type="checkbox" data-consent="${i.id}" ${S.customerConsent[i.id]?'checked':''}>I have reviewed the terms and voluntarily consent to ${esc(i.name)}${i.variant?' · '+esc(i.variant):''} at ${rupee(i.price)}.</label>`:''}</article>`).join('')||'<div class="card"><h2>Continue without add-ons</h2><p>No optional products have been shortlisted. Confirm this choice below.</p></div>'}<div class="card"><h2>How would you like to pay?</h2><p class="small muted">For the products you choose to accept.</p><div class="pillgroup"><label class="pill"><input type="radio" name="payment" value="loan" ${S.paymentMode==='loan'?'checked':''}><span>Add to my loan</span></label><label class="pill"><input type="radio" name="payment" value="separate" ${S.paymentMode==='separate'?'checked':''}><span>Pay separately</span></label></div><p id="payment-note" class="small muted" style="margin:14px 0 0">${!S.paymentMode?'Select your preferred payment option.':S.paymentMode==='loan'?'The amount is added to your requested loan. Financing interest may apply; final EMI is provided by the lending partner.':'Payment is handled separately. Giving consent does not collect money.'}</p></div><div class="dock"><div class="dock-inner" style="max-width:608px"><div><span class="small muted">Your selected benefits</span><div class="price" id="customer-total">${rupee(customerTotal())}</div></div><button class="btn" id="confirm-choices">Continue →</button></div></div>`;}
function customerOtp(){const p=S.customer;return `<button class="link back" id="edit-choices">← Review my choices</button><div class="card" style="margin-top:18px"><p class="eyebrow">FINAL CONFIRMATION</p><h1>Confirm it’s you.</h1><p class="muted">This demo displays a code on screen. No email is sent to <strong>${esc(p.application.email)}</strong>.</p>${summaryLine('Accepted benefits',rupee(p.acceptedTotal))}${summaryLine('Payment choice',p.paymentMode==='loan'?'Add to loan':p.paymentMode==='separate'?'Pay separately':'No add-ons')}<div class="divider"></div><button class="btn secondary full" id="request-otp">${S.otpSent?'Generate another demo code':'Show demo verification code'}</button><p class="small muted" style="margin-top:12px">The demo code expires after five minutes.</p>${S.demoCode?`<div class="demo-code" role="status">Demo code: <strong>${esc(S.demoCode)}</strong></div>`:''}<form id="otp-form">${field('Six-digit verification code','otp','','text','class="otp" inputmode="numeric" autocomplete="one-time-code" maxlength="6" pattern="[0-9]{6}" required placeholder="000000"')}<button class="btn full" type="submit">Verify & confirm my choices →</button></form><p class="small muted" style="margin:18px 0 0">Verification confirms only the product choices and consents you just reviewed.</p></div>`;}
function customerDone(){const p=S.customer;return `<div class="card center"><div class="success-mark">✓</div><p class="eyebrow">CHOICES CONFIRMED</p><h1>Your choices are confirmed.</h1><p class="muted">Your decisions have been shared with your representative.</p><span class="tag green">Demo code verified · ${date(p.verifiedAt)}</span></div><div class="card"><h2>Your final selection</h2>${p.quote.items.map(i=>summaryLine(esc(i.name),p.choices.find(c=>c.id===i.id)?.decision==='accept'?rupee(i.price):'Declined')).join('')||'<p>No optional products selected.</p>'}<div class="divider"></div>${summaryLine('Total accepted',rupee(p.acceptedTotal))}${summaryLine('Payment',p.paymentMode==='loan'?'Add to loan':p.paymentMode==='separate'?'Pay separately':'No add-ons')}<div class="note green" style="margin-top:16px">${p.paymentMode==='separate'?'Your payment is pending. Your representative will guide you through payment and loan processing.':'Your representative can now continue loan processing. Final loan approval and disbursement remain with the lending partner.'}</div></div><section class="card"><h2>Your consent record</h2><p class="small muted">Keep a copy of your product choices, disclosures and verification details.</p><button class="btn full" id="customer-download">Download my consent record ↓</button></section>`;}
function renderCustomer(){const p=S.customer;$('#app').innerHTML=`${head(true)}<main class="customer">${p.verifiedAt?customerDone():S.customerStage==='otp'?customerOtp():customerReview()}</main>`;
 $$('[data-disclosure]').forEach(el=>el.addEventListener('toggle',()=>{if(el.open){const box=el.querySelector('.terms');checkRead(box);}}));
 const checkRead=el=>{if(el.scrollTop+el.clientHeight>=el.scrollHeight-8){S.customerRead.add(el.dataset.termsScroll);const btn=$(`[data-id="${el.dataset.termsScroll}"][data-decision="accept"]`);if(btn&&S.customerChoices[el.dataset.termsScroll]!=='accept')btn.textContent='Accept product';}};
 $$('[data-terms-scroll]').forEach(el=>el.addEventListener('scroll',()=>checkRead(el)));
 $$('[data-decision]').forEach(el=>el.onclick=()=>{const id=el.dataset.id;if(el.dataset.decision==='accept'&&!S.customerRead.has(id)){reviewForAcceptance(id);return;}S.customerChoices[id]=el.dataset.decision;if(el.dataset.decision==='decline')S.customerConsent[id]=false;const y=scrollY;renderCustomer();scrollTo(0,y);});
 $$('[data-consent]').forEach(el=>el.onchange=()=>S.customerConsent[el.dataset.consent]=el.checked);
 $$('[name="payment"]').forEach(el=>el.onchange=()=>{S.paymentMode=el.value;$('#payment-note').textContent=el.value==='loan'?'The amount is added to your requested loan. Financing interest may apply; final EMI is provided by the lending partner.':'Payment is handled separately. Giving consent does not collect money.';});
 $('#confirm-choices')?.addEventListener('click',()=>act(async()=>{const choices=p.quote.items.map(i=>({id:i.id,decision:S.customerChoices[i.id],termsRead:S.customerRead.has(i.id),consent:!!S.customerConsent[i.id]}));const missing=choices.find(c=>!c.decision);if(missing){highlightConsent(missing.id);throw Error('Please choose accept or decline for '+p.quote.items.find(i=>i.id===missing.id).name+'.');}const unchecked=choices.find(c=>c.decision==='accept'&&!c.consent);if(unchecked){highlightConsent(unchecked.id);throw Error('Please tick the consent box for '+p.quote.items.find(i=>i.id===unchecked.id).name+'.');}if(choices.some(c=>c.decision==='accept')&&!S.paymentMode)throw Error('Please choose how you would like to pay.');if(!await confirmDeclines(choices))return;const r=await api('/customer/'+customerId+'/choices',{choices,paymentMode:S.paymentMode});S.customer=r.proposal;S.customerStage='otp';S.otpSent=false;S.demoCode='';renderCustomer();scrollTo(0,0);}));
 $('#request-otp')?.addEventListener('click',e=>act(async()=>{e.target.disabled=true;try{const r=await api('/customer/'+customerId+'/otp',{});S.otpSent=true;S.demoCode=r.demoCode;renderCustomer();toast('Demo verification code is shown on screen.');}finally{e.target.disabled=false;}}));
 $('#edit-choices')?.addEventListener('click',()=>{S.customerStage='review';renderCustomer();});
 $('#otp-form')?.addEventListener('submit',e=>{e.preventDefault();act(async()=>{const r=await api('/customer/'+customerId+'/verify',{otp:new FormData(e.target).get('otp')});S.customer=r.proposal;renderCustomer();scrollTo(0,0);});});
 $('#customer-download')?.addEventListener('click',()=>downloadConsentRecord(p));
}
async function init(){if(customerId){try{const r=await api('/customer/'+customerId);S.customer=r.proposal;for(const c of S.customer.choices||[]){S.customerChoices[c.id]=c.decision;S.customerConsent[c.id]=c.consent;if(c.termsRead)S.customerRead.add(c.id);}S.paymentMode=['loan','separate'].includes(S.customer.paymentMode)?S.customer.paymentMode:'';S.customerStage=S.customer.choices?'otp':'review';renderCustomer();}catch(e){$('#app').innerHTML=`${head(true)}<main class="customer"><div class="card"><h1>Unable to open this proposal.</h1><p>${esc(e.message)}</p><p>Please ask your representative for a fresh link.</p></div></main>`;}return;}try{await bootstrap();S.screen='home';}catch{S.screen='login';}render();}
init();
